# Validate the evidence contract and all referenced paths; use installed jsonschema if available.
def validate(value,schema,path='$'):
 if 'enum' in schema: assert value in schema['enum'],path
 kind=schema.get('type')
 if kind=='object':
  assert isinstance(value,dict),path
  assert set(schema.get('required',[]))<=set(value),path
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False:assert set(value)<=set(props),path
  for key,item in value.items():
   if key in props:validate(item,props[key],path+'.'+key)
 elif kind=='array':
  assert isinstance(value,list) and len(value)>=schema.get('minItems',0),path
  for i,item in enumerate(value):validate(item,schema['items'],path+'['+str(i)+']')
 elif kind=='string':assert isinstance(value,str) and len(value)>=schema.get('minLength',0),path
 elif kind in ('integer','number'):
  assert type(value) in ((int,) if kind=='integer' else (int,float)),path
  assert value>=schema.get('minimum',float('-inf')) and value<=schema.get('maximum',float('inf')),path
